struct Data { int val = 0; };

// Legacy function requires non-const pointer
void legacy_func(Data* d) { d->val = 100; }

void call_legacy_adapter(const Data& d) {
    // Safe only if 'd' was not defined as const originally
    Data* writable = const_cast<Data*>(&d);
    legacy_func(writable);
}

Data runtime_data;
call_legacy_adapter(runtime_data); // Legal usage

